g=[r+[9]*(25-len(r)) for r in g]
from collections import deque
H,W=len(g),len(g[0]); seen=set(); holes=[]
for i in range(H):
 for j in range(W):
  if g[i][j]==9 and (i,j) not in seen:
   q=deque([(i,j)]); seen.add((i,j)); comp=[]; border=False
   while q:
    x,y=q.popleft(); comp.append((x,y)); border |= x in (0,H-1) or y in (0,W-1)
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<H and 0<=ny<W and g[nx][ny]==9 and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   if not border: holes.append(comp)
[(len(c), (min(x for x,y in c), min(y for x,y in c), max(x for x,y in c), max(y for x,y in c)), sorted(c)[:10]) for c in holes]

for i,r in enumerate(g): print(i, len(r), ' '.join(map(str,r)))
out=[r[:] for r in g]
for c in holes:
 for i,j in c: out[i][j]=4
print('OUT')
print('\n'.join(' '.join(map(str,r)) for r in out))
